import {SID_INSTRUMENTS,SID_CATEGORIES,identifyInstrument,applyInstrument} from './sid-instruments.mjs';
import {Machine,PRESETS,freshProject,validateProject,DRIVER} from './machine.mjs';
import {hex} from './cpu.mjs';
import {assemble} from './assembler.mjs';
const $=id=>document.getElementById(id),storageKey='sid65-project-v1';
let project=freshProject(),storageOK=true;try{const p=localStorage.getItem(storageKey);if(p)project=validateProject(JSON.parse(p));}catch{storageOK=false;}
let local=new Machine(44100,project),audioContext,node,audioPromise,analyser,gain,playing=false,selectedVoice=0,octave=4,erase=false,brush=67,activeStep=-1,lastError=null,toastTimer,saveTimer,lastSID=[],scopeData=new Float32Array(512),state=local.snapshot();
const names=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'];
const noteName=n=>n===null?'·':names[n%12]+(Math.floor(n/12)-1);
const voiceNames=['PULSE','BASS','TEXTURE'],colors=['#a36a4c','#788760','#6e7d81'],stepColors=['#d4ae92','#b4c2a0','#b5c4bf'],stepBorders=['#b89a7d','#99ab85','#94aca3'];
const waveNames={16:'Triangle',32:'Saw',64:'Pulse',128:'Noise'};
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4300);}
function persist(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem(storageKey,JSON.stringify(project));$('save-status').textContent='Dein Muster ist in diesem Browser gespeichert.';storageOK=true;}catch{$('save-status').textContent='Browserspeicher nicht verfügbar. Bitte Projekt speichern.';storageOK=false;}},200);}
function send(type,extra={}){if(node)node.port.postMessage({type,...extra});}
function updateProject(reload=false){local.setProject(project);if(reload)local.load(project.source);send('project',{project,reload});persist();}
async function ensureAudio(){if(audioContext){await audioContext.resume();if(audioPromise)await audioPromise;return;}
 const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('Dieser Browser unterstützt Web Audio nicht. Bitte in einem aktuellen Browser öffnen.');
 audioContext=new AC({latencyHint:'interactive'});const resume=audioContext.resume();audioPromise=(async()=>{if(!audioContext.audioWorklet)throw Error('AudioWorklet fehlt. Bitte die HTTPS-Seite in einem aktuellen Browser öffnen.');await audioContext.audioWorklet.addModule(new URL('./worklet.mjs',import.meta.url));node=new AudioWorkletNode(audioContext,'sid-65',{numberOfInputs:0,numberOfOutputs:1,outputChannelCount:[1]});gain=audioContext.createGain();gain.gain.value=.75;analyser=audioContext.createAnalyser();analyser.fftSize=1024;scopeData=new Float32Array(analyser.fftSize);node.connect(gain).connect(analyser).connect(audioContext.destination);node.port.onmessage=({data})=>{if(data.type==='error'){toast(data.message);playing=false;updateTransport();return;}if(data.type==='state'){state=data.state;playing=state.playing;updateState();}};node.onprocessorerror=()=>{toast('Die Audioengine wurde unterbrochen. Bitte die Seite neu laden.');playing=false;updateTransport();};send('project',{project,reload:true});$('rate').textContent=(audioContext.sampleRate/1000).toFixed(1);await resume;})();try{await audioPromise;}catch(e){if(audioContext)await audioContext.close().catch(()=>{});audioContext=null;node=null;throw e;}finally{audioPromise=null;}}
function updateTransport(){$('play-icon').textContent=playing?'Ⅱ':'▶';$('play-label').textContent=playing?'Pause':audioContext?'Spielen':'Einschalten & spielen';$('play').classList.toggle('playing',playing);$('power-led').classList.toggle('on',playing||held.size>0);$('screen-title').textContent=playing?project.name.toUpperCase():'READY TO MAKE SOME NOISE';$('state-line').textContent=state.error?'CPU STOPPED':playing?'6502 RUNNING · SID ACTIVE':'6502 READY · SID STANDBY';}
function updateState(){updateTransport();$('step-screen').textContent=`${String(playing?state.position+1:0).padStart(2,'0')} / 16`;if(activeStep!==(playing?state.position:-1)){activeStep=playing?state.position:-1;document.querySelectorAll('.step').forEach(b=>b.classList.toggle('playhead',Number(b.dataset.step)===activeStep));}
 if(!$('cpu-view').hidden)renderMonitor();if(state.error&&state.error!==lastError){lastError=state.error;toast(state.error);}if(!state.error)lastError=null;}
function renderMonitor(){const c=state.cpu,regs=[['A',c.a,2],['X',c.x,2],['Y',c.y,2],['PC',c.pc,4],['SP',c.sp,2],['NV-BDIZC',c.p,2]];$('registers').replaceChildren(...regs.map(([n,v,w])=>{const d=document.createElement('div');d.className='register-cell';const l=document.createElement('span');l.textContent=n;const s=document.createElement('strong');s.textContent=n==='NV-BDIZC'?v.toString(2).padStart(8,'0'):'$'+hex(v,w);if(n==='NV-BDIZC')s.style.fontSize='13px';d.append(l,s);return d;}));$('instruction-count').textContent=c.instructions.toLocaleString('de-DE')+' INSTR.';
 const lines=state.trace?.length?state.trace:state.next;$('trace').replaceChildren(...lines.slice(-8).map(r=>{const d=document.createElement('div');d.className='trace-row';for(const text of ['$'+hex(r.address,4),r.bytes,r.text]){const s=document.createElement('span');s.textContent=text;d.append(s);}return d;}));
 const groups=[[0,7,'VOICE 1'],[7,14,'VOICE 2'],[14,21,'VOICE 3'],[21,25,'FILTER']];$('sid-registers').replaceChildren(...groups.map(([start,end,label])=>{const d=document.createElement('div');d.className='sid-registers-row';const l=document.createElement('span');l.textContent=label;d.append(l);for(let i=start;i<end;i++){const s=document.createElement('span');s.className='sid-byte'+(lastSID[i]!==state.registers[i]?' changed':'');s.textContent=hex(state.registers[i]);s.title='$'+hex(0xd400+i,4);d.append(s);}return d;}));lastSID=[...state.registers];}
const wavePaths={16:'M1 13 L8 1 L22 13 L29 1',32:'M1 13 L14 1 L14 13 L28 1 L28 13',64:'M1 13 V1 H12 V13 H23 V1 H29',128:'M1 7 L4 3 L7 12 L10 1 L13 9 L16 5 L19 13 L22 2 L25 9 L29 5'};
function instrumentOptions(v){const id=identifyInstrument(v);return `<option value="" ${!id?'selected':''}>Eigener Klang</option>`+SID_CATEGORIES.map(category=>`<optgroup label="${category}">${SID_INSTRUMENTS.filter(p=>p.category===category).map(p=>`<option value="${p.id}" ${id===p.id?'selected':''}>${p.name}</option>`).join('')}</optgroup>`).join('');}
function renderVoices(){$('voices').innerHTML=project.voices.map((v,i)=>`<section class="voice ${selectedVoice===i?'selected':''}" style="--voice-color:${colors[i]}"><div class="voice-head"><button class="voice-name" data-choose="${i}" aria-pressed="${selectedVoice===i}"><span class="voice-number">0${i+1}</span> STIMME ${i+1} <i class="voice-dot"></i></button><button class="mute" data-mute="${i}" aria-pressed="${v.mute}" aria-label="Stimme ${i+1} stummschalten">${v.mute?'MUTED':'MUTE'}</button></div><label class="sid-instrument-label">INSTRUMENT<select class="sid-instrument" data-instrument="${i}" aria-label="Instrument für SID-Stimme ${i+1}">${instrumentOptions(v)}</select></label><div class="wave-buttons">${[16,32,64,128].map(w=>`<button data-wave="${w}" data-voice="${i}" class="${v.wave===w?'active':''}" aria-label="Stimme ${i+1}: ${waveNames[w]}" aria-pressed="${v.wave===w}"><svg viewBox="0 0 30 14" aria-hidden="true"><path d="${wavePaths[w]}"/></svg>${waveNames[w].toUpperCase()}</button>`).join('')}</div><label class="parameter-row">PULSBREITE <input type="range" min="1" max="99" value="${v.pw}" data-param="pw" data-voice="${i}" aria-label="Pulsbreite Stimme ${i+1}"><output>${v.pw}%</output></label><div class="envelopes">${[['attack','A'],['decay','D'],['sustain','S'],['release','R']].map(([p,l])=>`<label>${l}<output>${v[p]}</output><input type="range" min="0" max="15" value="${v[p]}" data-param="${p}" data-voice="${i}" aria-label="${p} Stimme ${i+1}"></label>`).join('')}</div><div class="voice-options"><label><input type="checkbox" data-option="ring" data-voice="${i}" ${v.ring?'checked':''}> RING</label><label><input type="checkbox" data-option="sync" data-voice="${i}" ${v.sync?'checked':''}> SYNC</label></div></section>`).join('');$('keyboard-voice').textContent=`Stimme ${selectedVoice+1} · ${waveNames[project.voices[selectedVoice].wave]}`;}
function chooseVoice(i){releaseAll();selectedVoice=i;renderVoices();renderSequencer();}
function renderSequencer(){$('sequencer').innerHTML=`<div class="seq-header"><span></span>${Array.from({length:16},(_,i)=>`<span>${String(i+1).padStart(2,'0')}</span>`).join('')}</div>`+project.patterns.map((pat,v)=>`<div class="seq-row" style="--voice-color:${colors[v]};--step-color:${stepColors[v]};--step-border:${stepBorders[v]}"><button class="track-name ${selectedVoice===v?'selected':''}" data-track="${v}"><span>0${v+1}</span>${voiceNames[v]}</button>${pat.map((n,s)=>`<button class="step ${n===null?'':'filled'} ${activeStep===s?'playhead':''}" data-voice="${v}" data-step="${s}" aria-label="Stimme ${v+1}, Schritt ${s+1}: ${n===null?'Pause':noteName(n)}" aria-pressed="${n!==null}">${noteName(n)}</button>`).join('')}</div>`).join('');}
function renderControls(){$('tempo').value=project.bpm;for(const key of ['cutoff','resonance','echo']){$(key).value=key==='echo'?Math.round(project[key]*100):project[key];effectLabel(key);}renderVoices();renderSequencer();$('code').value=project.source;const index=PRESETS.findIndex(p=>p.name===project.name);$('preset').value=index<0?0:index;}
function effectLabel(key){$(key+'-value').textContent=key==='echo'?Math.round(project.echo*100)+'%':key==='cutoff'?Math.round(project.cutoff/2047*100)+'%':project.resonance;}
function drawKeyboard(){const whites=[0,2,4,5,7,9,11,12],blacks=[[1,1],[3,2],[6,4],[8,5],[10,6]],base=(octave+1)*12;let html=whites.map((n,i)=>`<button class="key white" data-note="${base+n}" aria-label="${noteName(base+n)}"><span>${['A','S','D','F','G','H','J','K'][i]}</span></button>`).join('');html+=blacks.map(([n,pos])=>`<button class="key black" data-note="${base+n}" style="left:calc(${pos/8*100}% - 3.75%)" aria-label="${noteName(base+n)}"><span>${{1:'W',3:'E',6:'T',8:'Y',10:'U'}[n]}</span></button>`).join('');$('keyboard').innerHTML=html;$('octave-label').textContent=`C${octave} — C${octave+1}`;}
const held=new Map();let holdOrder=0;
function paintKeys(){document.querySelectorAll('.key').forEach(k=>k.classList.toggle('pressed',[...held.values()].some(n=>n.note===Number(k.dataset.note))));updateTransport();}
async function press(token,note){if(held.has(token))return;const item={voice:selectedVoice,note,order:++holdOrder};held.set(token,item);paintKeys();try{await ensureAudio();if(held.get(token)===item)send('on',{voice:item.voice,note});}catch(e){held.delete(token);paintKeys();toast(e.message);}}
function release(token){const item=held.get(token);if(!item)return;held.delete(token);const same=[...held.values()].filter(n=>n.voice===item.voice).sort((a,b)=>b.order-a.order);if(same.length)send('on',{voice:item.voice,note:same[0].note});else send('off',{voice:item.voice});paintKeys();}
function releaseAll(){for(const k of [...held.keys()])release(k);}
$('keyboard').addEventListener('pointerdown',e=>{const k=e.target.closest('.key');if(!k)return;e.preventDefault();k.setPointerCapture(e.pointerId);press('p'+e.pointerId,Number(k.dataset.note));});for(const ev of ['pointerup','pointercancel','lostpointercapture'])$('keyboard').addEventListener(ev,e=>release('p'+e.pointerId));
const keyboardKeys={'a':0,'w':1,'s':2,'e':3,'d':4,'f':5,'t':6,'g':7,'y':8,'h':9,'u':10,'j':11,'k':12,'z':8};
window.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();if(!e.repeat)$('play').click();return;}const key=e.key.toLowerCase();if(key in keyboardKeys&&!e.repeat){e.preventDefault();press('k'+key,(octave+1)*12+keyboardKeys[key]);}});window.addEventListener('keyup',e=>release('k'+e.key.toLowerCase()));window.addEventListener('blur',releaseAll);document.addEventListener('visibilitychange',()=>{if(document.hidden)releaseAll();});
$('play').onclick=async()=>{try{await ensureAudio();releaseAll();if(playing){send('stop');playing=false;}else{send('play');playing=true;}updateTransport();}catch(e){toast(e.message);}};
$('stop').onclick=()=>{releaseAll();send('panic');local=new Machine(44100,project);state=local.snapshot();playing=false;updateState();};
$('preset').innerHTML=PRESETS.map((p,i)=>`<option value="${i}">${p.name}</option>`).join('');
$('preset').onchange=()=>{const running=playing;releaseAll();send('stop');project=freshProject(Number($('preset').value));local=new Machine(44100,project);updateProject(true);renderControls();state=local.snapshot();if(running)send('play');toast(PRESETS[Number($('preset').value)].desc);};
$('tempo').onchange=()=>{project.bpm=Math.round(Math.max(40,Math.min(220,Number($('tempo').value)||94)));$('tempo').value=project.bpm;updateProject();};
$('voices').addEventListener('click',e=>{const w=e.target.closest('[data-wave]'),m=e.target.closest('[data-mute]'),v=e.target.closest('[data-choose]');if(w){project.voices[w.dataset.voice].wave=Number(w.dataset.wave);renderVoices();updateProject();}if(m){const i=Number(m.dataset.mute);project.voices[i].mute=!project.voices[i].mute;renderVoices();updateProject();}if(v)chooseVoice(Number(v.dataset.choose));});
$('voices').addEventListener('change',e=>{const t=e.target;if(t.dataset.instrument!==undefined&&t.value){releaseAll();const preset=applyInstrument(project,+t.dataset.instrument,t.value);selectedVoice=+t.dataset.instrument;updateProject();renderVoices();renderSequencer();toast(preset.name+' geladen. Spiele die Klaviatur oder dein Muster.');}});
$('voices').addEventListener('input',e=>{const t=e.target;if(t.dataset.param){project.voices[t.dataset.voice][t.dataset.param]=Number(t.value);t.parentElement.querySelector('output').textContent=t.value+(t.dataset.param==='pw'?'%':'');updateProject();}if(t.dataset.option){project.voices[t.dataset.voice][t.dataset.option]=t.checked;updateProject();}if(t.dataset.voice!==undefined&&(t.dataset.param||t.dataset.option)){document.querySelector(`[data-instrument="${t.dataset.voice}"]`).value=identifyInstrument(project.voices[t.dataset.voice]);}});
$('note-brush').innerHTML=Array.from({length:73},(_,i)=>`<option value="${i+24}">${noteName(i+24)}</option>`).join('');$('note-brush').value=brush;$('note-brush').onchange=()=>{brush=Number($('note-brush').value);erase=false;$('erase').setAttribute('aria-pressed','false');};$('erase').onclick=()=>{erase=!erase;$('erase').setAttribute('aria-pressed',erase);};
$('sequencer').onclick=e=>{const b=e.target.closest('[data-step]'),t=e.target.closest('[data-track]');if(t)chooseVoice(Number(t.dataset.track));if(b){const v=Number(b.dataset.voice),s=Number(b.dataset.step);project.patterns[v][s]=erase||project.patterns[v][s]===brush?null:brush;selectedVoice=v;renderVoices();renderSequencer();updateProject();}};
for(const [id,dir]of [['transpose-down',-1],['transpose-up',1]])$(id).onclick=()=>{project.patterns[selectedVoice]=project.patterns[selectedVoice].map(n=>n===null?null:Math.max(24,Math.min(96,n+dir)));renderSequencer();updateProject();};$('clear-voice').onclick=()=>{project.patterns[selectedVoice].fill(null);renderSequencer();updateProject();};
for(const [id,dir]of [['oct-down',-1],['oct-up',1]])$(id).onclick=()=>{releaseAll();octave=Math.max(1,Math.min(6,octave+dir));drawKeyboard();};
for(const key of ['cutoff','resonance','echo'])$(key).oninput=()=>{project[key]=Number($(key).value)/(key==='echo'?100:1);effectLabel(key);updateProject();};
function setTab(cpu){$('sound-view').hidden=cpu;$('cpu-view').hidden=!cpu;for(const [id,on]of [['sound-tab',!cpu],['cpu-tab',cpu]]){$(id).classList.toggle('active',on);$(id).setAttribute('aria-selected',on);}if(cpu)renderMonitor();}
$('cpu-tab').onclick=()=>setTab(true);$('sound-tab').onclick=()=>setTab(false);for(const id of ['cpu-tab','sound-tab'])$(id).onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const cpu=id==='sound-tab';setTab(cpu);$(cpu?'cpu-tab':'sound-tab').focus();}};
$('single-step').onclick=async()=>{try{releaseAll();if(node){send('step');}else{state=local.debugStep();playing=false;updateState();}}catch(e){toast(e.message);}};
$('compile').onclick=()=>{try{const source=$('code').value,p=assemble(source);local.load(source);project.source=source;send('load',{source});persist();$('compile-status').textContent=`${p.writes.length} Bytes geladen · PLAY bei $${hex(p.entry,4)}. Die nächste Routine verwendet deinen Code.`;if(!node){state=local.snapshot();renderMonitor();}toast('Maschinencode geladen.');}catch(e){$('compile-status').textContent=e.message;toast(e.message);}};
$('restore-code').onclick=()=>{$('code').value=DRIVER;$('compile').click();};
$('code').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const t=e.target,start=t.selectionStart;t.setRangeText('  ',start,t.selectionEnd,'end');}if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();$('compile').click();}};
function download(data,type,name){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
$('save-project').onclick=()=>download(JSON.stringify(project,null,2),'application/json','SID65-Projekt.json');$('load-project').onclick=()=>$('file-input').click();$('file-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error('Projektdatei ist zu groß.');const next=validateProject(JSON.parse(await file.text()));releaseAll();send('stop');project=next;local=new Machine(44100,project);updateProject(true);renderControls();state=local.snapshot();playing=false;updateState();toast('Projekt geladen.');}catch(e){toast(e.message);}finally{$('file-input').value='';}};
$('download-prg').onclick=()=>{try{const p=assemble(project.source),m=new Machine(44100,project);const start=Math.min(0x1000,...p.writes.map(x=>x[0])),end=Math.max(0x3018,...p.writes.map(x=>x[0]));const bytes=new Uint8Array(end-start+3);bytes[0]=start&255;bytes[1]=start>>8;bytes.set(m.mem.slice(start,end+1),2);download(bytes,'application/octet-stream','SID65-Code-und-Tabellen.prg');toast('PRG mit Code und Tabellen. PLAY als Subroutine aufrufen; kein BASIC-Startprogramm.');}catch(e){toast(e.message);}};
$('export-wav').onclick=()=>{const button=$('export-wav');button.disabled=true;button.textContent='RENDERT …';let worker;try{worker=new Worker(new URL('./render-worker.mjs',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.error)toast(data.error);else{download(data.buffer,'audio/wav','SID65-Vier-Takte.wav');toast('Vier Takte plus vier Sekunden Ausklang exportiert.');}finish();};worker.onerror=()=>{toast('WAV-Export konnte nicht gestartet werden.');finish();};worker.postMessage({project});}catch(e){toast(e.message);finish();}function finish(){worker?.terminate();button.disabled=false;button.innerHTML='↓ WAV <span>4 TAKTE</span>';}};
$('about-button').onclick=()=>{$('about').open=true;$('about').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});};
const canvas=$('scope'),ctx=canvas.getContext('2d');let frame=0;
function draw(){requestAnimationFrame(draw);if(document.hidden)return;if(++frame%2)return;const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);}const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#2c3b2c';ctx.lineWidth=1;ctx.beginPath();for(let x=0;x<w;x+=w/12){ctx.moveTo(x,0);ctx.lineTo(x,h);}for(let y=0;y<h;y+=h/6){ctx.moveTo(0,y);ctx.lineTo(w,y);}ctx.stroke();if(analyser)analyser.getFloatTimeDomainData(scopeData);else scopeData.fill(0);let start=0;for(let i=1;i<scopeData.length/2;i++){if(scopeData[i-1]<0&&scopeData[i]>=0){start=i;break;}}const len=Math.min(scopeData.length-start,512);ctx.beginPath();for(let i=0;i<len;i++){const x=i/(len-1)*w,y=h*.51-scopeData[start+i]*h*.47;if(!i)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.strokeStyle='#b9d89e';ctx.lineWidth=1.5*dpr;ctx.shadowBlur=6*dpr;ctx.shadowColor='#9fc680';ctx.stroke();ctx.shadowBlur=0;}
renderControls();drawKeyboard();renderMonitor();updateState();draw();if(!storageOK)$('save-status').textContent='Projektdateien lassen sich unten speichern und laden.';
